const getBestandsuebersicht = `-- name: GetBestandsuebersicht :many
select charge,
       lagerplatz_bezeichnung,
       lagerplatz_id,
       eilager_kz,
       eilager_id,
       eilager_bezeichnung,
       sum(jumbos)   as jumbos,
       sum(xl)       as xl,
       sum(large)    as large,
       sum(medium)   as medium,
       sum(small)    as small,
       sum(volleikg) as volleikg
from (
         -- positive buchungen (einlagerung / ziel einer umbuchung)
         select eb.charge,
                lp.bezeichnung as lagerplatz_bezeichnung,
                lp.id          as lagerplatz_id,
                e.kz           as eilager_kz,
                eb.id_eilager  as eilager_id,
                e.bezeichnung  as eilager_bezeichnung,
                eb.jumbos,
                eb.xl,
                eb.large,
                eb.medium,
                eb.small,
                eb.volleikg
         from eilagerbuchung eb
                  left join eilager e on eb.id_eilager = e.id
                  left join lagerplatz lp on eb.id_lagerplatz = lp.id
         where (? = 0 or eb.id_eilager = ?)

         union all

         -- negative buchungen (abgang / quelle einer umbuchung)
         select eb.charge,
                ''                 as lagerplatz_bezeichnung,
                0                  as lagerplatz_id,
                e.kz               as eilager_kz,
                eb.id_fremdeslager as eilager_id,
                e.bezeichnung      as eilager_bezeichnung,
                -eb.jumbos,
                -eb.xl,
                -eb.large,
                -eb.medium,
                -eb.small,
                -eb.volleikg
         from eilagerbuchung eb
                  left join eilager e on eb.id_fremdeslager = e.id
         where eb.id_fremdeslager != 0 and (? = 0 or eb.id_fremdeslager = ?))
group by charge, lagerplatz_id, eilager_id, eilager_kz, eilager_bezeichnung
order by eilager_bezeichnung, charge, lagerplatz_bezeichnung
`

type GetBestandsuebersichtParams struct {
	Column1        interface{} `json:"column_1"`
	IDEilager      int32       `json:"id_eilager"`
	Column3        interface{} `json:"column_3"`
	IDFremdeslager int32       `json:"id_fremdeslager"`
}

type GetBestandsuebersichtRow struct {
	Charge                string         `json:"charge"`
	LagerplatzBezeichnung sql.NullString `json:"lagerplatz_bezeichnung"`
	LagerplatzID          sql.NullInt32  `json:"lagerplatz_id"`
	EilagerKz             sql.NullString `json:"eilager_kz"`
	EilagerID             int32          `json:"eilager_id"`
	EilagerBezeichnung    sql.NullString `json:"eilager_bezeichnung"`
	Jumbos                interface{}    `json:"jumbos"`
	Xl                    interface{}    `json:"xl"`
	Large                 interface{}    `json:"large"`
	Medium                interface{}    `json:"medium"`
	Small                 interface{}    `json:"small"`
	Volleikg              interface{}    `json:"volleikg"`
}

func (q *Queries) GetBestandsuebersicht(ctx context.Context, arg GetBestandsuebersichtParams) ([]GetBestandsuebersichtRow, error) {
	rows, err := q.db.QueryContext(ctx, getBestandsuebersicht,
		arg.Column1,
		arg.IDEilager,
		arg.Column3,
		arg.IDFremdeslager,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetBestandsuebersichtRow
	for rows.Next() {
		var i GetBestandsuebersichtRow
		if err := rows.Scan(
			&i.Charge,
			&i.LagerplatzBezeichnung,
			&i.LagerplatzID,
			&i.EilagerKz,
			&i.EilagerID,
			&i.EilagerBezeichnung,
			&i.Jumbos,
			&i.Xl,
			&i.Large,
			&i.Medium,
			&i.Small,
			&i.Volleikg,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

